dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "input"
    },
    {
      "parameter": "region",
      "label": "Region",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true"
    },
    {
      "parameter": "credibleSetId",
      "label": "Credible Set Id",
      "type": "input"
    },
    {
      "parameter": "variant",
      "label": "Variant ID",
      "type": "input"
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "kp_phenotypes",
      "header": "Phenotypes in Knowledge Portals",
      "data point": {
        "type": "api",
        "url": "https://bioindex.hugeamp.org/api/portal/phenotypes?q=a2f",
        "data type": "json",
        "data wrapper": [
          "data"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "description"
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "name"
          },
          {
            "type": "raw",
            "field name": "Set Phenotype",
            "raw field": "name"
          },
          {
            "type": "raw",
            "field name": "Group",
            "raw field": "group"
          },
          {
            "type": "raw",
            "field name": "Dichotomous",
            "raw field": "dichotomous"
          }
        ],
        "top rows": [
          "Phenotype",
          "ID",
          "Group",
          "Dichotomous",
          "Set Phenotype"
        ],
        "column formatting": {
          "Set Phenotype": {
            "type": [
              "set parameter"
            ],
            "parameter": "phenotype"
          }
        }
      },
      "filters": [
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "ID",
          "label": "Phenotype ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Group",
          "label": "Group",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "global_associations",
      "header": "Global Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "global-associations",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "join multi",
            "field name": "Clumped Region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Set Region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Variant Sifter",
            "fields to join": [
              "phenotype",
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              "&region=",
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Err",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z-Score",
            "raw field": "zScore"
          },
          {
            "type": "array to string",
            "field name": "Nearest Genes",
            "raw field": "nearest",
            "separate by": ","
          },
          {
            "type": "calculate",
            "field name": "pLog10",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          },
          "Nearest Genes": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          },
          "Set Region": {
            "type": [
              "set parameter"
            ],
            "parameter": "region"
          },
          "Variant Sifter": {
            "type": [
              "link"
            ],
            "link to": "/research.html?pageid=kp_variant_sifter&phenotype=",
            "new tab": "true",
            "link type": "button",
            "link label": "Open"
          },
          "MAF": {
            "type": [
              "fixed 4",
              "render background percent"
            ],
            "percent if empty": 0
          },
          "Standard Err": {
            "type": [
              "fixed 4",
              "render background percent"
            ],
            "percent if empty": 0
          },
          "Z-Score": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          }
        },
        "top rows": [
          "Variant ID",
          "P-Value",
          "Beta",
          "MAF",
          "Standard Err",
          "Z-Score",
          "Clumped Region",
          "Nearest Genes",
          "Variant Sifter",
          "Set Region"
        ],
        "locus field": "Clumped Region"
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (<= or >=)",
          "type": "search or",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "type": "manhattan bitmap plot",
        "x axis field": "Clumped Region",
        "y axis field": "pLog10",
        "render by": "Variant ID",
        "y axis label": "P-Value(-Log10)",
        "x axis label": "SNPs",
        "hover content": [
          "Variant ID",
          "P-Value",
          "Beta"
        ],
        "height": "250"
      }
    },
    {
      "section id": "associations",
      "header": "Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Odds Ratio",
            "raw field": "oddsRatio"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "Ref/Alt",
          "P-Value",
          "-log10(P-Value)",
          "Beta",
          "Odds Ratio",
          "EAF",
          "MAF",
          "Standard Error",
          "Z Score"
        ],
        "locus field": "Locus",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "type": "region plot",
        "x axis field": "position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "ld server": {
          "pos": "position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
    {
      "section id": "credible_sets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "top rows": [
          "Credible Set ID",
          "Dataset",
          "Method",
          "PMID",
          "Region",
          "Set Credible Set ID"
        ],
        "column formatting": {
          "Set Credible Set ID": {
            "type": [
              "set parameter"
            ],
            "parameter": "credibleSetId"
          }
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Set Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          }
        ]
      }
    },
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "credibleSetId"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "top rows": [
          "Variant ID",
          "Posterior Probability",
          "P-Value",
          "EAF",
          "MAF",
          "Standard Err",
          "Ancestry",
          "Set Variant ID"
        ],
        "column formatting": {
          "Set Variant ID": {
            "type": [
              "set parameter"
            ],
            "parameter": "variant"
          }
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "Set Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "Posterior Probability",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Err",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          }
        ]
      }
    },
    {
      "section id": "transcript_consequences",
      "header": "Transcript Consequences",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "transcript-consequences",
        "parameters": [
          "variant"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "filters": [
        {
          "field": "Impact",
          "label": "Impact",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "top rows": [
          "Feature",
          "Impact",
          "Position",
          "Amino Acids",
          "consequence",
          "HGNC",
          "HGVSc",
          "HGVSp",
          "SIFT Prediction",
          "LRT",
          "CADD-Phred Score",
          "gnomAD AF"
        ],
        "data convert": [
          {
            "type": "raw",
            "field name": "Feature",
            "raw field": "transcriptId"
          },
          {
            "type": "raw",
            "field name": "Impact",
            "raw field": "impact"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "proteinEnd"
          },
          {
            "type": "raw",
            "field name": "Amino Acids",
            "raw field": "aminoAcids"
          },
          {
            "type": "array to string",
            "field name": "consequence",
            "raw field": "consequenceTerms",
            "separate by": ","
          },
          {
            "type": "raw",
            "field name": "HGNC",
            "raw field": "hgncId"
          },
          {
            "type": "raw",
            "field name": "HGVSc",
            "raw field": "hgvsc"
          },
          {
            "type": "raw",
            "field name": "HGVSp",
            "raw field": "hgvsp"
          },
          {
            "type": "raw",
            "field name": "SIFT Prediction",
            "raw field": "siftPrediction"
          },
          {
            "type": "raw",
            "field name": "LRT",
            "raw field": "proveanPred"
          },
          {
            "type": "raw",
            "field name": "CADD-Phred Score",
            "raw field": "caddRawRankscore"
          },
          {
            "type": "raw",
            "field name": "gnomAD AF",
            "raw field": "gnomadGenomesPopmaxAf"
          }
        ]
      }
    }
  ]
}
